(function(){'use strict';if(document.body.dataset.tool!=='fabrication')return;const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,$=k=>document.getElementById('t-'+k),E=window.HVACDuctwork,form=document.getElementById('ductwork-form'),F=n=>Number(n).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:3});
const read=()=>Object.fromEntries([...form.querySelectorAll('input,select')].filter(e=>e.id.startsWith('t-')).map(e=>[e.id.slice(2),e.tagName==='SELECT'?e.value:Number(e.value)]));
const write=values=>{for(const [k,v] of Object.entries(values))$(k).value=v;};
function reveal(input){let d=input.closest('details');while(d){d.open=true;d=d.parentElement.closest('details');}input.focus();input.scrollIntoView?.({block:'nearest'});}
function describe(){const x=read(),joint=$('jointPreset'),stiff=$('stiffenerPreset');document.getElementById('dw-summary-0').textContent=(x.shape==='round'?'Ø '+F(x.a):F(x.a)+' × '+F(x.b))+' mm · t '+F(x.t)+' mm';document.getElementById('dw-summary-1').textContent=joint.selectedOptions[0].textContent+' · '+stiff.selectedOptions[0].textContent;document.getElementById('dw-summary-2').textContent=(x.insulation>0?F(x.insulation)+' mm · '+F(x.insDensity)+' kg/m³':L('Không cách nhiệt','No insulation'))+' · '+L('Hao hụt ','Waste ')+F(x.waste)+'%';
 document.getElementById('dw-setup-1').textContent=L('Bích/nẹp: ','Joint: ')+F(x.jointLinearMass)+' kg/m · '+L('Tăng cứng: ','Stiffener: ')+F(x.stiffenerLinearMass)+' kg/m'+(x.joint==='tdf'?' · '+L('Cộng mỗi đầu ','Allowance per end ')+F(x.endAllowance)+' mm':'')+'. '+L('Khối lượng lý thuyết; chọn Chỉnh chi tiết để thay số liệu thực.','Theoretical mass; use detailed parameters for actual data.');document.getElementById('dw-setup-2').textContent=L('Mí dọc ','Longitudinal seams ')+x.seams+' × '+F(x.seam)+' mm · '+L('Cộng đầu đoạn ','End allowance ')+F(x.endAllowance)+' mm. '+L('Đã điền mẫu, chỉ cần mở chi tiết nếu khác thực tế.','Example values are filled; open details only when different.');
 document.getElementById('dw-auto-status').textContent=thickness()==null?L('Ngoài phạm vi tự chọn (ống chữ nhật tôn mạ kẽm, cạnh 100–4000 mm, áp suất −400…+1000 Pa). Giữ thông số hiện tại; hãy tự chỉnh.','Outside automatic scope (rectangular galvanized duct, 100–4000 mm longer side, −400…+1000 Pa). Current values are retained; adjust manually.'):L('Tự chọn: tôn 0,6 / 0,8 / 1,0 / 1,2 mm theo cạnh lớn; bích góc L25 (≤800), L30 (≤1500), L40 (>1500 mm). Đây là cấu hình khởi đầu để tính vật tư; bạn có thể đổi bất kỳ lúc nào.','Automatic starting values: 0.6 / 0.8 / 1.0 / 1.2 mm by longer side; angle flanges L25 (≤800), L30 (≤1500), L40 (>1500 mm). These are quantity-estimation defaults; edit at any time.');$('stiffenerSpacing').closest('.calc-field').hidden=x.stiffenerLinearMass===0;for(const k of ['insulation','insDensity'])$(k).closest('.calc-field').hidden=x.insulationPreset!=='custom';}
const manualMap={joint:'jointPreset',jointLinearMass:'jointPreset',endFrames:'jointPreset',endAllowance:'jointPreset',stiffenerLinearMass:'stiffenerPreset',insulation:'insulationPreset',insDensity:'insulationPreset'};
function autoSetup(){const x=read(),t=thickness();if(x.thicknessMode==='auto'&&t!=null)write({t});if(x.jointMode==='auto'&&t!=null){const side=Math.max(x.a,x.b),preset=side<=800?'angle25':side<=1500?'angle30':'angle40';write({...E.jointSetup(preset,x),jointPreset:preset});}}
function choice(event){const k=event.target.id?.replace(/^t-/,'');if(!k)return;const x=read();if(k==='t')$('thicknessMode').value='manual';if(k==='jointPreset'||['joint','jointLinearMass','endFrames','endAllowance'].includes(k))$('jointMode').value='manual';
if(k==='jointPreset'&&x.jointPreset!=='custom')write(E.jointSetup(x.jointPreset,x));else if(k==='stiffenerPreset'&&x.stiffenerPreset!=='custom')write({stiffenerLinearMass:x.stiffenerPreset==='none'?0:E.angleMass(Number(x.stiffenerPreset.slice(5)),3)});else if(k==='insulationPreset'&&x.insulationPreset!=='custom'){const v=x.insulationPreset==='none'?[0,48]:x.insulationPreset.split('-').map(Number);write({insulation:v[0],insDensity:v[1]});}else if(manualMap[k])$(manualMap[k]).value='custom';
if(['a','b','shape','material','pressure','thicknessMode','jointMode'].includes(k))autoSetup();if(['jointPreset','stiffenerPreset'].includes(k)&&$(k).value==='custom')document.getElementById('dw-advanced-1').open=true;describe();}
document.addEventListener('hvac-fabrication-load',describe);form.addEventListener('input',choice,true);form.addEventListener('change',choice,true);form.addEventListener('input',describe);form.addEventListener('change',describe);document.getElementById('dw-reset').addEventListener('click',describe);
document.addEventListener('hvac-project-restore',e=>{const old=e.detail?.calculation?.x||{};for(const k of ['jointPreset','stiffenerPreset','insulationPreset'])if(!old[k])$(k).value='custom';for(const k of ['thicknessMode','jointMode'])if(!old[k])$(k).value='manual';describe();});document.addEventListener('hvac-project-transfer',e=>{const params=new URLSearchParams(e.detail||{});for(const [raw,preset] of Object.entries(manualMap))if(params.has(raw)&&!params.has(preset))$(preset).value='custom';if(params.has('t')&&!params.has('thicknessMode'))$('thicknessMode').value='manual';if([...params.keys()].some(k=>['joint','jointPreset','jointLinearMass','endFrames','endAllowance'].includes(k))&&!params.has('jointMode'))$('jointMode').value='manual';autoSetup();form.dispatchEvent(new Event('input',{bubbles:true}));describe();});const initial=new URLSearchParams(location.search);for(const [raw,preset] of Object.entries(manualMap))if(initial.has(raw)&&!initial.has(preset))$(preset).value='custom';if(initial.has('t')&&!initial.has('thicknessMode'))$('thicknessMode').value='manual';if([...initial.keys()].some(k=>['joint','jointPreset','jointLinearMass','endFrames','endAllowance'].includes(k))&&!initial.has('jointMode'))$('jointMode').value='manual';
function thickness(){const x=read(),side=Math.max(x.a,x.b);if(x.shape!=='rect'||x.material!=='steel'||x.pressure< -400||x.pressure>1000||side<100||side>4000)return null;return side<=400?.6:side<=800?.8:side<=2000?1:1.2;}
function dialog(kind){document.getElementById('fabrication-help-dialog')?.remove();const d=document.createElement('dialog');d.id='fabrication-help-dialog';d.className='fabrication-help-dialog';d.setAttribute('aria-label',kind==='thickness'?L('Gợi ý chiều dày tôn','Sheet thickness help'):L('Chọn chiều dài đoạn chế tạo','Fabricated section length help'));const title=kind==='thickness'?L('Gợi ý chọn chiều dày tôn','Sheet thickness suggestion'):L('Chọn chiều dài đoạn chế tạo','Choose fabricated section length');
 const t=thickness();d.innerHTML=`<div class="panel-title"><h2>${title}</h2><button type="button" class="text-button" data-close>${L('Đóng','Close')}</button></div>`+(kind==='thickness'?`<p>${L('Dùng để chọn nhanh mẫu cho ống chữ nhật tôn mạ kẽm áp thấp (−400…+1000 Pa). Cạnh lớn là kích thước ngoài đang nhập. Chế độ Tự chọn cập nhật khi đổi kích thước; chỉnh tay sẽ giữ giá trị của bạn.','Quick starting values for low-pressure rectangular galvanized duct (−400…+1000 Pa). The longer side uses the current outside dimensions. Automatic mode updates the value when dimensions change; manual edits are retained.')}</p><table class="calc-output-table"><thead><tr><th>${L('Cạnh lớn','Longer side')}</th><th>${L('Giá trị gợi ý','Starting value')}</th></tr></thead><tbody><tr><td>100–400 mm</td><td>0.6 mm</td></tr><tr><td>&gt;400–800 mm</td><td>0.8 mm</td></tr><tr><td>&gt;800–2000 mm</td><td>1.0 mm</td></tr><tr><td>&gt;2000–4000 mm</td><td>1.2 mm</td></tr></tbody></table><p>${L('Các mức nhập nhanh giúp ước tính vật tư cho hệ thông gió thông thường. Chỉnh theo vật liệu, áp suất và phương án gia công/lắp đặt thực tế.','Quick-entry values help estimate materials for ordinary ventilation. Adjust for the actual material, pressure and fabrication/installation method.')}</p><p>${t==null?L('Điều kiện hiện tại nằm ngoài phạm vi gợi ý này. Hãy tự chọn theo cấu tạo dự kiến.','Current conditions are outside this suggestion. Choose the intended construction manually.'):L('Với kích thước hiện tại, có thể bắt đầu từ ','For the current dimensions, start with ')+F(t)+' mm.'}</p>${t==null?'':`<button type="button" class="calc-link" data-apply-thickness>${L('Dùng','Use')} ${F(t)} mm</button>`}`:`<p>${L('1,2 m là giá trị mẫu dễ bắt đầu. Chiều dài hữu dụng phụ thuộc cạnh tôn đặt theo chiều dọc đoạn, phần cộng tại hai đầu và phần dự phòng cắt; còn cần kiểm tra khả năng vận chuyển và lắp đặt.','1.2 m is a convenient example. Usable length depends on the sheet dimension along the duct axis, allowances at both ends and cutting reserve; also check transport and installation constraints.')}</p><label>${L('Cạnh tôn theo chiều dọc đoạn','Sheet dimension along the duct axis')} (m)<input data-stock type="number" value="1.22" min="0.2" max="6" step="any"></label><p>${L('Phần cộng mỗi đầu đang dùng','Current allowance per end')}: ${F(read().endAllowance)} mm · ${L('Dự phòng cắt mẫu','Example cutting reserve')}: 20 mm.</p><p>${L('Dài hữu dụng = cạnh tôn − 2 × phần cộng đầu − dự phòng cắt. Ví dụ bích rời không cộng đầu: 1,22 − 0,02 = 1,20 m.','Usable length = sheet dimension − 2 × end allowance − cutting reserve. Example with separate flanges and no end allowance: 1.22 − 0.02 = 1.20 m.')}</p><p data-length-result role="status"></p><button type="button" class="calc-link" data-apply-length>${L('Dùng chiều dài này','Use this length')}</button>`);document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();if(kind==='thickness')d.querySelector('[data-apply-thickness]')?.addEventListener('click',()=>{const v=thickness();if(v!=null){$('t').value=v;$('thicknessMode').value='manual';form.dispatchEvent(new Event('input',{bubbles:true}));d.close();reveal($('t'));}});else{const stock=d.querySelector('[data-stock]'),apply=d.querySelector('[data-apply-length]');function length(){const value=Math.floor((Number(stock.value)-2*read().endAllowance/1000-.02)*100+1e-8)/100;const valid=stock.value.trim()!==''&&stock.validity.valid&&value>=.1&&value<=6;apply.disabled=!valid;d.querySelector('[data-length-result]').textContent=valid?L('Chiều dài có thể dùng: ','Usable length: ')+F(value)+' m':L('Kiểm tra khổ tôn và phần cộng đầu.','Check sheet size and end allowances.');return valid?value:null;}stock.addEventListener('input',length);length();apply.onclick=()=>{const value=length();if(value!=null){$('section').value=value;form.dispatchEvent(new Event('input',{bubbles:true}));d.close();reveal($('section'));}};}d.showModal();}
const status=document.createElement('p');status.id='dw-auto-status';status.className='field-help';document.getElementById('dw-group-0').append(status);document.querySelectorAll('[data-fab-help]').forEach(b=>b.addEventListener('click',()=>dialog(b.dataset.fabHelp)));autoSetup();form.dispatchEvent(new Event('input',{bubbles:true}));describe();
})();
